-- BLOG DE TUCONSULTOR · tabla + RLS + 365 posts programados
create table if not exists public.blog_tuconsultor (
  id bigint generated always as identity primary key,
  slug text unique not null,
  titulo text not null,
  extracto text,
  contenido text not null,
  imagen text,
  serie text,
  fecha_publicacion date not null,
  creado timestamptz default now()
);
alter table public.blog_tuconsultor enable row level security;
drop policy if exists blog_tc_lectura_publica on public.blog_tuconsultor;
create policy blog_tc_lectura_publica on public.blog_tuconsultor
  for select using (fecha_publicacion <= current_date);
drop policy if exists blog_tc_escritura_equipo on public.blog_tuconsultor;
create policy blog_tc_escritura_equipo on public.blog_tuconsultor
  for all using (public.mi_rol() in ('superadmin','admin','consultor','gestion'))
  with check (public.mi_rol() in ('superadmin','admin','consultor','gestion'));

