insert into public.blog_tuconsultor (slug,titulo,extracto,contenido,imagen,serie,fecha_publicacion) values ('2026-08-07-iso-9004','¿Es ISO 9004 para tu organización? Señales de que sí.','Si tus clientes (o la Administración) empiezan a pedírtelo, si has crecido y "todo está en la cabeza de dos personas", o si quieres diferenciarte en licitaciones: sí, es para ti.','<p>Si tus clientes (o la Administración) empiezan a pedírtelo, si has crecido y &quot;todo está en la cabeza de dos personas&quot;, o si quieres diferenciarte en licitaciones: sí, es para ti.</p><p>Llevamos tu ISO 9001 un paso más allá con ISO 9004: autoevaluación de madurez y mejora del sistema orientada al éxito sostenido de la organización.</p><h2>Cómo lo trabajamos en TuConsultor</h2><p>Diagnóstico realista, diseño e implantación con documentación a medida, auditoría interna y acompañamiento hasta el final — con el nivel de servicio que elijas: Relación, Implicación, Compromiso o Apoyo.</p><p><a href="https://www.tuconsultor.com/areas/calidad/iso-9004.html">→ Conoce el servicio</a> · <a href="https://www.tuconsultor.com/contacto.html">Pide tu cita</a></p>','https://www.tuconsultor.com/social-img/iso-9004.png','NORMAS','2026-08-07') on conflict (slug) do nothing;
