insert into public.blog_tuconsultor (slug,titulo,extracto,contenido,imagen,serie,fecha_publicacion) values ('2027-01-24-huella-de-carbono','¿Es Huella de Carbono · ISO 14064 para tu organización? Señales de que sí.','Si tus clientes (o la Administración) empiezan a pedírtelo, si has crecido y "todo está en la cabeza de dos personas", o si quieres diferenciarte en licitaciones: sí, es para ti.','<p>Si tus clientes (o la Administración) empiezan a pedírtelo, si has crecido y &quot;todo está en la cabeza de dos personas&quot;, o si quieres diferenciarte en licitaciones: sí, es para ti.</p><p>Calculamos tu huella de carbono de organización conforme a ISO 14064 y GHG Protocol, y te acompañamos en el registro del MITECO y la verificación.</p><h2>Cómo lo trabajamos en TuConsultor</h2><p>Diagnóstico realista, diseño e implantación con documentación a medida, auditoría interna y acompañamiento hasta el final — con el nivel de servicio que elijas: Relación, Implicación, Compromiso o Apoyo.</p><p><a href="https://www.tuconsultor.com/areas/sostenibilidad/huella-de-carbono.html">→ Conoce el servicio</a> · <a href="https://www.tuconsultor.com/contacto.html">Pide tu cita</a></p>','https://www.tuconsultor.com/social-img/huella-de-carbono.png','NORMAS','2027-01-24') on conflict (slug) do nothing;
