insert into public.blog_tuconsultor (slug,titulo,extracto,contenido,imagen,serie,fecha_publicacion) values ('2027-02-13-pacto-mundial','¿Es Pacto Mundial para tu organización? Señales de que sí.','Si tus clientes (o la Administración) empiezan a pedírtelo, si has crecido y "todo está en la cabeza de dos personas", o si quieres diferenciarte en licitaciones: sí, es para ti.','<p>Si tus clientes (o la Administración) empiezan a pedírtelo, si has crecido y &quot;todo está en la cabeza de dos personas&quot;, o si quieres diferenciarte en licitaciones: sí, es para ti.</p><p>Te ayudamos a adherirte al Pacto Mundial y a elaborar tus informes de progreso anuales con evidencias sólidas.</p><h2>Cómo lo trabajamos en TuConsultor</h2><p>Diagnóstico realista, diseño e implantación con documentación a medida, auditoría interna y acompañamiento hasta el final — con el nivel de servicio que elijas: Relación, Implicación, Compromiso o Apoyo.</p><p><a href="https://www.tuconsultor.com/areas/sostenibilidad/pacto-mundial.html">→ Conoce el servicio</a> · <a href="https://www.tuconsultor.com/contacto.html">Pide tu cita</a></p>','https://www.tuconsultor.com/social-img/pacto-mundial.png','NORMAS','2027-02-13') on conflict (slug) do nothing;
